use vstd::prelude::*;
use std::collections::HashSet;

verus! {

/// Removes duplicate values from the input vector `nums`.
/// 
/// The returned vector `res` has the following properties:
/// 1. No duplicate elements.
/// 2. The set of elements in `res` is exactly the set of elements in `nums`.
/// 3. The relative order of first occurrences in `nums` is preserved in `res`.
fn remove_duplicates(nums: Vec<i32>) -> (res: Vec<i32>)
    ensures
        // 1. No duplicate elements in `res`.
        forall i: nat, j: nat ::
            i < j && j < res.len() ==>
                res[i] != res[j],
        // 2. The set of elements in `res` is exactly the set of elements in `nums`.
        forall x: i32 ::
            (exists i: nat :: i < nums.len() && nums[i] == x)
            <=>
            (exists j: nat :: j < res.len() && res[j] == x),
        // 3. The relative order of first occurrences in `nums` is preserved in `res`.
        forall i: nat, j: nat ::
            i < j && j < nums.len() &&
            (forall k: nat :: k < i ==> nums[k] != nums[i]) &&
            (forall k: nat :: k < j ==> nums[k] != nums[j])
            ==>
            // both nums[i] and nums[j] appear in `res`
            (exists p: nat :: p < res.len() && res[p] == nums[i]) &&
            (exists q: nat :: q < res.len() && res[q] == nums[j]) &&
            // and in the same order
            forall p: nat, q: nat ::
                p < res.len() && res[p] == nums[i] &&
                q < res.len() && res[q] == nums[j] ==>
                p < q,
{
    let mut seen = HashSet::new();
    let mut res = Vec::new();

    for x in nums {
        // `HashSet::insert` returns true iff `x` was not already in `seen`.
        if seen.insert(x) {
            res.push(x);
        }
    }

    res
}

} // end of `verus!`


fn main() {
    let v1 = vec![1, 2, 3, 2, 4, 1, 5];
    let v2 = remove_duplicates(v1.clone());
    println!("Input: {:?}\nOutput: {:?}", v1, v2);

    let v3: Vec<i32> = vec![];
    let v4 = remove_duplicates(v3.clone());
    println!("Input: {:?}\nOutput: {:?}", v3, v4);
}